{{--
  Fixed columns (fixedColumns()): the same measuring as @acunsoft/datatable-dom's
  pinColumns(), as an Alpine x-init. Pinned cells get adt-pin and a sticky offset
  from the header row (at most 60% of the visible width); it runs again after
  every Livewire update and resize.
  No double quotes: this is printed inside an attribute.
--}}
(() => { const root = $el, start = {{ (int) $start }}, end = {{ (int) $end }}; let observer; const apply = () => { observer?.disconnect(); const table = root.querySelector('table.adt-table'); const head = table?.tHead?.rows[table.tHead.rows.length - 1]; if (table && head) { const cells = [...head.cells]; const first = cells.findIndex(cell => cell.classList.contains('adt-th')); let startCount = start > 0 ? Math.min(cells.length, (first < 0 ? 0 : first) + start) : 0; let endCount = Math.min(end, cells.length - startCount); const width = i => cells[i].getBoundingClientRect().width; const sum = (from, to) => { let total = 0; for (let i = from; i < to; i++) total += width(i); return total; }; const visible = (table.parentElement || root).getBoundingClientRect().width; const startWidth = sum(0, startCount); if (visible > 0 && startWidth + sum(cells.length - endCount, cells.length) > visible * 0.6) endCount = 0; if (visible > 0 && startWidth > visible * 0.6) startCount = 0; const pins = new Map(); for (let i = 0, x = 0; i < startCount; i++) { pins.set(i, ['start', x, i === startCount - 1]); x += width(i); } for (let i = cells.length - 1, x = 0; i >= cells.length - endCount; i--) { pins.set(i, ['end', x, i === cells.length - endCount]); x += width(i); } for (const row of table.rows) { if (row.cells.length !== cells.length) continue; [...row.cells].forEach((cell, i) => { const pin = pins.get(i); cell.classList.toggle('adt-pin', !!pin); cell.classList.toggle('adt-pin--edge-start', !!pin && pin[0] === 'start' && pin[2]); cell.classList.toggle('adt-pin--edge-end', !!pin && pin[0] === 'end' && pin[2]); cell.style.left = pin && pin[0] === 'start' ? pin[1] + 'px' : ''; cell.style.right = pin && pin[0] === 'end' ? pin[1] + 'px' : ''; }); } } observer.observe(root, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'style'] }); }; let queued = false; const schedule = () => { if (queued) return; queued = true; queueMicrotask(() => { queued = false; apply(); }); }; observer = new MutationObserver(schedule); apply(); if (window.ResizeObserver) new ResizeObserver(schedule).observe(root); })()